'use client'

import type { LucideIcon } from 'lucide-react'
import { TrendingUp, TrendingDown } from 'lucide-react'
import { cn } from '@/lib/utils'

interface KpiCardProps {
  label: string
  value: string | number
  subtext: string
  icon: LucideIcon
  trend?: 'up' | 'down' | 'neutral'
  invertTrend?: boolean
  loading?: boolean
  index?: number
  accentColor?: string
}

function TrendBadge({
  trend,
  invertTrend,
  subtext,
}: {
  trend: 'up' | 'down' | 'neutral'
  invertTrend: boolean
  subtext: string
}) {
  const isPositive = invertTrend ? trend === 'down' : trend === 'up'
  const isNeutral = trend === 'neutral'

  if (isNeutral || !subtext) {
    return <p className="mt-2.5 text-xs text-muted-foreground">{subtext}</p>
  }

  return (
    <div className="mt-2.5 flex items-center gap-1.5">
      <span
        className={cn(
          'inline-flex items-center gap-0.5 rounded-full px-1.5 py-0.5 text-[11px] font-semibold',
          isPositive
            ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400'
            : 'bg-red-50 text-red-700 dark:bg-red-500/15 dark:text-red-400',
        )}
      >
        {isPositive ? (
          <TrendingUp className="h-3 w-3" aria-hidden="true" />
        ) : (
          <TrendingDown className="h-3 w-3" aria-hidden="true" />
        )}
        {subtext}
      </span>
    </div>
  )
}

export function KpiCard({
  label,
  value,
  subtext,
  icon: Icon,
  trend = 'neutral',
  invertTrend = false,
  index = 0,
  accentColor = 'oklch(52% 0.24 292)',
}: KpiCardProps) {
  return (
    <div
      className={cn(
        'group relative overflow-hidden rounded-xl bg-card',
        'border border-border',
        'shadow-[var(--shadow-card)]',
        'transition-all duration-150 ease-out',
        'hover:shadow-[var(--shadow-card-hover)] hover:-translate-y-px',
        'animate-fade-in-up p-5',
      )}
      style={{
        animationDelay: `${index * 60}ms`,
        animationFillMode: 'both',
        ['--kpi-accent' as string]: accentColor,
      }}
    >
      {/* Left accent bar (3px, full height) */}
      <div
        className="absolute inset-y-0 left-0 w-[3px] rounded-l-xl"
        style={{ background: `var(--kpi-accent)` }}
        aria-hidden="true"
      />

      {/* Label + icon row */}
      <div className="mb-3 flex items-center justify-between">
        <span className="text-xs font-medium uppercase tracking-[0.06em] text-muted-foreground">
          {label}
        </span>
        <div
          className="flex h-8 w-8 items-center justify-center rounded-lg"
          style={{ background: `color-mix(in oklch, var(--kpi-accent) 12%, transparent)` }}
        >
          <Icon
            className="h-4 w-4"
            style={{ color: `var(--kpi-accent)` }}
            aria-hidden="true"
          />
        </div>
      </div>

      {/* Value */}
      <div className="text-[2.125rem] font-bold tabular-nums leading-none tracking-tight text-foreground">
        {value}
      </div>

      {/* Trend / subtext */}
      <TrendBadge trend={trend} invertTrend={invertTrend} subtext={subtext} />
    </div>
  )
}

import { Skeleton } from '@/components/ui/skeleton'

export function KpiCardSkeleton() {
  return (
    <div className="relative overflow-hidden rounded-xl border border-border bg-card p-5 shadow-[var(--shadow-card)]">
      {/* Left accent bar placeholder */}
      <Skeleton className="absolute inset-y-0 left-0 w-[3px] rounded-l-xl" />
      {/* Label + icon */}
      <div className="mb-3 flex items-center justify-between">
        <Skeleton className="h-3.5 w-24 rounded-full" />
        <Skeleton className="h-8 w-8 rounded-lg" />
      </div>
      {/* Value */}
      <Skeleton className="mb-2 h-9 w-28 rounded-md" />
      {/* Trend */}
      <Skeleton className="h-5 w-16 rounded-full" />
    </div>
  )
}

import type { Metadata } from 'next'
import { CalendarDays, Users, DollarSign } from 'lucide-react'

export const metadata: Metadata = {
  title: {
    default: 'Sign in',
    template: '%s | InkOS',
  },
}

interface AuthLayoutProps {
  children: React.ReactNode
}

const FEATURE_BULLETS = [
  { icon: CalendarDays, text: 'Bookings, schedule & waitlist in one view' },
  { icon: Users, text: 'Client CRM with full session history' },
  { icon: DollarSign, text: 'Commissions, payroll & billing — automated' },
] as const

/**
 * Split-screen auth layout — light mode default.
 * Left panel (lg+): brand panel with light purple gradient.
 * Right panel: form card on soft background.
 */
export default function AuthLayout({ children }: AuthLayoutProps) {
  return (
    <div className="flex min-h-svh bg-[oklch(96%_0.008_264)]">
      {/* Left panel — desktop only */}
      <div
        className="relative hidden lg:flex lg:w-5/12 xl:w-[44%] flex-col justify-between overflow-hidden p-10"
        style={{ background: 'oklch(52% 0.24 292)' }}
      >
        {/* Subtle mesh glows */}
        <div
          className="pointer-events-none absolute inset-0"
          aria-hidden="true"
          style={{
            background:
              'radial-gradient(ellipse 70% 60% at 80% 10%, oklch(65% 0.20 292 / 0.4), transparent), radial-gradient(ellipse 50% 50% at 20% 90%, oklch(60% 0.22 230 / 0.3), transparent)',
          }}
        />

        {/* Logo */}
        <div className="relative z-10 flex items-center gap-2.5">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-white/20 ring-1 ring-white/30">
            <span className="text-xs font-bold text-white">IO</span>
          </div>
          <span className="text-lg font-semibold tracking-tight text-white">InkOS</span>
        </div>

        {/* Feature list */}
        <div className="relative z-10 space-y-6">
          <h2 className="text-2xl font-bold leading-snug tracking-tight text-white">
            The operating system for modern tattoo studios.
          </h2>
          <ul className="space-y-4">
            {FEATURE_BULLETS.map(({ icon: Icon, text }) => (
              <li key={text} className="flex items-center gap-3 text-sm text-white/80">
                <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-white/[0.15] ring-1 ring-white/20">
                  <Icon className="h-3.5 w-3.5 text-white" aria-hidden="true" />
                </div>
                {text}
              </li>
            ))}
          </ul>
        </div>

        {/* Social proof */}
        <p className="relative z-10 text-xs text-white/50">
          Trusted by 500+ tattoo studios worldwide
        </p>
      </div>

      {/* Right panel — form */}
      <div className="flex flex-1 flex-col items-center justify-center p-6 lg:p-10">
        <div className="w-full max-w-[420px]">
          <div className="rounded-2xl border border-border bg-card p-8 shadow-[var(--shadow-soft-md)]">
            {children}
          </div>
          <p className="mt-4 text-center text-xs text-muted-foreground">
            The OS for Modern Ink Studios
          </p>
        </div>
      </div>
    </div>
  )
}

